#!/usr/bin/env python3
"""Simple Wolfram|Alpha query script or fallback calculator"""
import sys
import os
import re

def query_wolfram(query):
    app_id = os.environ.get('WOLFRAM_APP_ID')
    if not app_id:
        return None
    try:
        import requests
        url = 'https://api.wolframalpha.com/v1/result'
        params = {'appid': app_id, 'i': query}
        response = requests.get(url, params=params)
        return response.text
    except:
        return None

def compute_local(query):
    """Basic local computation for verification"""
    query = query.lower().strip()

    # Sum calculations
    if 'sum' in query:
        nums = re.findall(r'[-\d.]+', query)
        if nums:
            return sum(float(n) for n in nums)

    # Mean calculations  
    if 'mean' in query or 'average' in query:
        nums = re.findall(r'[-\d.]+', query)
        if nums:
            return sum(float(n) for n in nums) / len(nums)

    return None

if __name__ == '__main__':
    query = ' '.join(sys.argv[1:])
    result = query_wolfram(query)
    if result is None:
        result = compute_local(query)
        if result is not None:
            print(f"Local computation: {result}")
        else:
            print(f"Could not compute: {query}")
    else:
        print(result)
EOF
